// ============================================================================
// FreeLang Query Context 모듈 - 쿼리 실행 컨텍스트
// ============================================================================
// 목표: 쿼리 실행 중 임시 값, 세션 정보, 성능 메트릭을 관리하는 컨텍스트
// 원리:
//   1. TempValue: 변수 ID → 임시 값 매핑 (정수/문자열 dual-type)
//   2. QueryContext: 세션, 쿼리 ID, 임시 값 배열, 타이밍 메타데이터
//   3. var_id 검색: for 루프로 is_used 플래그 추적하며 탐색
// 구조:
//   - 상수 정의 (에러 코드 150-151, 제한값)
//   - TempValue, QueryContext 구조체
//   - 컨텍스트 생성/정리
//   - 임시 값 set/get (정수/문자열)
//   - 통계 조회
// ============================================================================

module query_context {
    // === 에러 코드 ===
    const QCTX_OK:           i32 = 0;
    const QCTX_ERR_NOTFOUND: i32 = 150;
    const QCTX_ERR_FULL:     i32 = 151;

    // === 제한값 ===
    const MAX_TEMP_VALUES: i32 = 256;

    // === 데이터 구조체 ===

    // 임시 값 슬롯 (정수/문자열 dual-type)
    struct TempValue {
        var_id:  i32;
        val_int: i64;
        val_str: string;
        is_used: bool;
    }

    // 쿼리 실행 컨텍스트
    struct QueryContext {
        session_id:  i64;
        query_id:    i64;
        temp_values: [TempValue];
        temp_count:  i32;
        start_ts:    i64;
        step_count:  i32;
    }

    // === 컨텍스트 생성/정리 ===

    // 새 쿼리 컨텍스트 생성
    func query_context_new(session_id: i64) -> QueryContext {
        var qc: QueryContext;
        qc.session_id = session_id;
        qc.query_id = 0;
        qc.temp_values = make([TempValue], MAX_TEMP_VALUES);
        qc.temp_count = 0;
        qc.start_ts = 1000; // 카운터 기반 시간 (초기값)
        qc.step_count = 0;
        return qc;
    }

    // === 임시 값 관리 ===

    // 임시 정수 값 설정 (기존이면 업데이트, 없으면 추가)
    func (qc: *QueryContext) query_context_set_temp_int(var_id: i32, val: i64) -> i32 {
        // 기존 var_id 검색
        var i: i32 = 0;
        while i < qc.temp_count {
            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
                // 기존 슬롯 업데이트
                qc.temp_values[i].val_int = val;
                return QCTX_OK;
            }
            i = i + 1;
        }

        // 새 슬롯 추가
        if qc.temp_count >= MAX_TEMP_VALUES {
            return QCTX_ERR_FULL;
        }

        qc.temp_values[qc.temp_count].var_id = var_id;
        qc.temp_values[qc.temp_count].val_int = val;
        qc.temp_values[qc.temp_count].val_str = "";
        qc.temp_values[qc.temp_count].is_used = true;
        qc.temp_count = qc.temp_count + 1;

        return QCTX_OK;
    }

    // 임시 문자열 값 설정 (기존이면 업데이트, 없으면 추가)
    func (qc: *QueryContext) query_context_set_temp_str(var_id: i32, val: string) -> i32 {
        // 기존 var_id 검색
        var i: i32 = 0;
        while i < qc.temp_count {
            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
                // 기존 슬롯 업데이트
                qc.temp_values[i].val_str = val;
                return QCTX_OK;
            }
            i = i + 1;
        }

        // 새 슬롯 추가
        if qc.temp_count >= MAX_TEMP_VALUES {
            return QCTX_ERR_FULL;
        }

        qc.temp_values[qc.temp_count].var_id = var_id;
        qc.temp_values[qc.temp_count].val_int = 0;
        qc.temp_values[qc.temp_count].val_str = val;
        qc.temp_values[qc.temp_count].is_used = true;
        qc.temp_count = qc.temp_count + 1;

        return QCTX_OK;
    }

    // 임시 정수 값 조회
    func (qc: *QueryContext) query_context_get_temp_int(var_id: i32) -> (i64, i32) {
        var i: i32 = 0;
        while i < qc.temp_count {
            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
                return (qc.temp_values[i].val_int, QCTX_OK);
            }
            i = i + 1;
        }
        return (0, QCTX_ERR_NOTFOUND);
    }

    // 임시 문자열 값 조회
    func (qc: *QueryContext) query_context_get_temp_str(var_id: i32) -> (string, i32) {
        var i: i32 = 0;
        while i < qc.temp_count {
            if qc.temp_values[i].var_id == var_id && qc.temp_values[i].is_used {
                return (qc.temp_values[i].val_str, QCTX_OK);
            }
            i = i + 1;
        }
        return ("", QCTX_ERR_NOTFOUND);
    }

    // === 컨텍스트 상태 관리 ===

    // 모든 임시 값 초기화
    func (qc: *QueryContext) query_context_clear_temps() -> i32 {
        var i: i32 = 0;
        while i < qc.temp_count {
            qc.temp_values[i].var_id = 0;
            qc.temp_values[i].val_int = 0;
            qc.temp_values[i].val_str = "";
            qc.temp_values[i].is_used = false;
            i = i + 1;
        }
        qc.temp_count = 0;
        return QCTX_OK;
    }

    // 쿼리 실행 종료 (메트릭 기록)
    func (qc: *QueryContext) query_context_end() -> i32 {
        qc.step_count = qc.step_count + 1;
        return QCTX_OK;
    }

    // === 통계 조회 ===

    // 컨텍스트 상태 문자열 표현
    func (qc: *QueryContext) query_context_stats() -> string {
        var result: string = "";
        result = result + "QueryContext {session_id: ";
        result = result + string(qc.session_id);
        result = result + ", query_id: ";
        result = result + string(qc.query_id);
        result = result + ", temp_count: ";
        result = result + string(qc.temp_count);
        result = result + ", step_count: ";
        result = result + string(qc.step_count);
        result = result + "}";
        return result;
    }
}

