// ============================================================================
// FreeLang Query Context 테스트
// ============================================================================
// 목표: query_context 모듈의 기능성 및 에러 처리 검증
// 범위:
//   - 컨텍스트 생성 및 초기화
//   - 임시 값 set/get (정수/문자열)
//   - 중복 설정 (업데이트)
//   - 에러 처리 (NOTFOUND, FULL)
//   - 컨텍스트 정리
//   - 통계 조회
// ============================================================================

module query_context_test {
    use query_context;

    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name: name,
            passed: condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_equal_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func assert_equal_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func assert_equal_str(actual: string, expected: string, name: string) -> TestResult {
        let passed = actual == expected;
        var msg: string = if passed { "PASS" } else { "FAIL" };
        return TestResult{
            name: name,
            passed: passed,
            message: msg,
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[✓]" } else { "[✗]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 테스트 함수 ===

    func test_context_new() {
        print("\n=== Test 1: query_context_new ===");
        let qc = query_context_new(1001);

        print_result(assert_equal_i64(qc.session_id, 1001, "session_id 초기화"));
        print_result(assert_equal_i64(qc.query_id, 0, "query_id 초기화"));
        print_result(assert_equal_i32(qc.temp_count, 0, "temp_count 초기화"));
        print_result(assert_equal_i32(qc.step_count, 0, "step_count 초기화"));
        print_result(assert_equal_i64(qc.start_ts, 1000, "start_ts 초기화"));
    }

    func test_set_temp_int() {
        print("\n=== Test 2: query_context_set_temp_int ===");
        var qc = query_context_new(2001);

        // 첫 번째 변수 설정
        let res1 = qc.query_context_set_temp_int(10, 100);
        print_result(assert_equal_i32(res1, 0, "설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 1, "temp_count = 1"));

        // 두 번째 변수 설정
        let res2 = qc.query_context_set_temp_int(20, 200);
        print_result(assert_equal_i32(res2, 0, "두 번째 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 2, "temp_count = 2"));
    }

    func test_set_temp_str() {
        print("\n=== Test 3: query_context_set_temp_str ===");
        var qc = query_context_new(3001);

        // 첫 번째 문자열 변수 설정
        let res1 = qc.query_context_set_temp_str(11, "hello");
        print_result(assert_equal_i32(res1, 0, "문자열 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 1, "temp_count = 1"));

        // 두 번째 문자열 변수 설정
        let res2 = qc.query_context_set_temp_str(12, "world");
        print_result(assert_equal_i32(res2, 0, "두 번째 문자열 설정 성공"));
        print_result(assert_equal_i32(qc.temp_count, 2, "temp_count = 2"));
    }

    func test_get_temp_int() {
        print("\n=== Test 4: query_context_get_temp_int ===");
        var qc = query_context_new(4001);

        // 값 설정
        qc.query_context_set_temp_int(10, 555);

        // 존재하는 값 조회
        let (val, err) = qc.query_context_get_temp_int(10);
        print_result(assert_equal_i64(val, 555, "값 조회 성공"));
        print_result(assert_equal_i32(err, 0, "에러 코드 OK"));

        // 존재하지 않는 값 조회
        let (val2, err2) = qc.query_context_get_temp_int(999);
        print_result(assert_equal_i32(err2, 150, "NOTFOUND 에러"));
    }

    func test_get_temp_str() {
        print("\n=== Test 5: query_context_get_temp_str ===");
        var qc = query_context_new(5001);

